/**
 * Micro-SaaS benchmarks — 190 small software businesses with real revenue.
 *
 * Imported 2026-08-02 from Adam's Google Sheet, "190+ Micro-SaaS Ideas Making
 * Millions", via the Drive connector.
 *
 * WHAT THIS IS NOT: humanity's problems. One-page checkout software and Shopify
 * SMS tools are not biosecurity. Nothing here belongs in the ranked index, and
 * mixing it in would be the same category error as treating virality as demand.
 *
 * WHAT IT IS: a calibration set. This is the only dataset on the site where a
 * real, small, solo-buildable business reports actual revenue, so it answers a
 * question the humanity index cannot — what does a small good quest actually
 * earn, and what did it cost to start?
 *
 * Three uses it genuinely serves:
 *   1. A floor for the starter packs. The median here is $40k/month, and 23 of
 *      190 started at $0. That is the realistic shape of a first company.
 *   2. `revenuePerVisitorUsd` is a rare, honest willingness-to-pay signal —
 *      money per unit of attention, measured rather than estimated. The `wtp`
 *      demand class is still hand-seeded; this is the closest thing to ground
 *      truth for it that exists here.
 *   3. `solopreneurScore` is someone else's feasibility model, useful as a
 *      cross-check on our own readiness gate.
 *
 * PROVENANCE CAVEAT: these figures are self-reported founder numbers compiled
 * from public interviews and directories. They are not audited, and the set is
 * survivorship-biased by construction — it is a list of businesses that WORKED.
 * Treat it as a reference for what is achievable, never as a base rate.
 */

export type MicroSaasBenchmark = {
  idea: string
  monthlyRevenueUsd: number | null
  monthlyTraffic: number | null
  /** Money per visitor — the willingness-to-pay signal. */
  revenuePerVisitorUsd: number | null
  startingCostsUsd: number | null
  /** 0-100, from the source sheet. Someone else's feasibility model. */
  solopreneurScore: number | null
  icp: string
  growthTactics: string
}

