const withRevenue = microSaasBenchmarks.filter((b) => b.monthlyRevenueUsd != null)

/** Median monthly revenue across the set — the calibration number. */
export function medianMonthlyRevenue(): number {
  const v = withRevenue.map((b) => b.monthlyRevenueUsd as number).sort((a, b) => a - b)
  if (v.length === 0) return 0
  const mid = Math.floor(v.length / 2)
  return v.length % 2 ? v[mid] : Math.round((v[mid - 1] + v[mid]) / 2)
}

/** Businesses that began with no capital at all. The permission argument. */
export function zeroCostStarts(): MicroSaasBenchmark[] {
  return microSaasBenchmarks.filter((b) => b.startingCostsUsd === 0)
}

/** Median revenue per visitor, where reported. A real WTP anchor. */
export function medianRevenuePerVisitor(): number | null {
  const v = microSaasBenchmarks
    .map((b) => b.revenuePerVisitorUsd)
    .filter((x): x is number => x != null)
    .sort((a, b) => a - b)
  if (v.length === 0) return null
  const mid = Math.floor(v.length / 2)
  return v.length % 2 ? v[mid] : (v[mid - 1] + v[mid]) / 2
}
